<?php
namespace App\Http\Controllers;
use App\Models\Firma; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class DepoController extends Controller {
private function firmaSec(Request $r){abort_unless(auth()->check()&&(auth()->user()->tamSistemYetkisiVarMi()||auth()->user()->isAdmin()||auth()->user()->isYedekParca()),403);$sistemYoneticisi=auth()->user()->tamSistemYetkisiVarMi();$id=$sistemYoneticisi?($r->integer('firma_id')?:session('aktif_firma_id')?:Firma::where('aktif',true)->orderBy('unvan')->value('id')):auth()->user()->firmaPersoneli?->firma_id;abort_unless($id&&Firma::where('id',$id)->where('aktif',true)->exists(),403);return (int)$id;}
public function index(Request $request){$firmaId=$this->firmaSec($request);$firmalar=auth()->user()->tamSistemYetkisiVarMi()?Firma::where('aktif',true)->orderBy('unvan')->get():Firma::where('id',$firmaId)->get();$depolar=DB::table('depolar')->where('firma_id',$firmaId)->where('aktif',true)->get();$raflar=DB::table('depo_raflar')->join('depolar','depolar.id','=','depo_raflar.depo_id')->where('depolar.firma_id',$firmaId)->where('depo_raflar.aktif',true)->select('depo_raflar.*','depolar.ad as depo_adi')->get();$cariler=DB::table('cari_hesaplar')->where('firma_id',$firmaId)->where('aktif',true)->orderBy('unvan')->get(['id','unvan','plaka']);$parcalar=DB::table('stok_parcalar')->leftJoin('stok_parca_raf_adresleri','stok_parca_raf_adresleri.stok_parca_id','=','stok_parcalar.id')->leftJoin('depo_raflar','depo_raflar.id','=','stok_parca_raf_adresleri.depo_raf_id')->leftJoin('depolar','depolar.id','=','depo_raflar.depo_id')->where('stok_parcalar.firma_id',$firmaId)->select('stok_parcalar.*','depo_raflar.kod as raf_kodu','depolar.ad as depo_adi')->latest('stok_parcalar.id')->get();$kaynaklar=DB::table('stok_urun_kaynaklari')->where('firma_id',$firmaId)->orderBy('ad')->get();$ozet=['toplam'=>$parcalar->count(),'kritik'=>$parcalar->filter(fn($p)=>$p->stok_miktari<=$p->minimum_stok)->count(),'bekleyen'=>$parcalar->where('oem_durum','kontrol_bekliyor')->count()];return view('depo.index-v2',compact('firmalar','firmaId','parcalar','ozet','depolar','raflar','cariler','kaynaklar'));}
public function barkod(Request $request){$firmaId=$this->firmaSec($request);$firmalar=auth()->user()->tamSistemYetkisiVarMi()?Firma::where('aktif',true)->orderBy('unvan')->get():Firma::where('id',$firmaId)->get();$arama=trim((string)$request->input('ara'));$depolar=DB::table('depolar')->where('firma_id',$firmaId)->where('aktif',true)->get();$raflar=DB::table('depo_raflar')->join('depolar','depolar.id','=','depo_raflar.depo_id')->where('depolar.firma_id',$firmaId)->select('depo_raflar.*','depolar.ad as depo_adi')->get();$parcalar=DB::table('stok_parcalar')->leftJoin('stok_parca_raf_adresleri','stok_parca_raf_adresleri.stok_parca_id','=','stok_parcalar.id')->leftJoin('depo_raflar','depo_raflar.id','=','stok_parca_raf_adresleri.depo_raf_id')->leftJoin('depolar','depolar.id','=','depo_raflar.depo_id')->where('stok_parcalar.firma_id',$firmaId)->when($arama!=='',fn($q)=>$q->where('stok_parcalar.parca_adi','like',"%{$arama}%"))->select('stok_parcalar.*','depo_raflar.kod as raf_kodu','depolar.ad as depo_adi')->get();return view('depo.barkod-v2',compact('firmalar','firmaId','arama','parcalar','depolar','raflar'));}
public function depoKaydet(Request $r){$id=$this->firmaSec($r);$v=$r->validate(['ad'=>['required','string','max:100']]);DB::table('depolar')->insert(['firma_id'=>$id,'ad'=>$v['ad'],'aktif'=>true,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Depo oluşturuldu.');}
public function rafKaydet(Request $r){$id=$this->firmaSec($r);$v=$r->validate(['depo_id'=>['required','exists:depolar,id'],'kod'=>['required','string','max:60']]);abort_unless(DB::table('depolar')->where('id',$v['depo_id'])->where('firma_id',$id)->exists(),403);DB::table('depo_raflar')->insert(['depo_id'=>$v['depo_id'],'kod'=>$v['kod'],'aktif'=>true,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Raf adresi oluşturuldu.');}
public function rafAta(Request $r){$id=$this->firmaSec($r);$v=$r->validate(['stok_parca_id'=>['required','exists:stok_parcalar,id'],'depo_raf_id'=>['required','exists:depo_raflar,id']]);abort_unless(DB::table('stok_parcalar')->where('id',$v['stok_parca_id'])->where('firma_id',$id)->exists(),403);abort_unless(DB::table('depo_raflar')->join('depolar','depolar.id','=','depo_raflar.depo_id')->where('depo_raflar.id',$v['depo_raf_id'])->where('depolar.firma_id',$id)->exists(),403);DB::table('stok_parca_raf_adresleri')->where('stok_parca_id',$v['stok_parca_id'])->update(['ana_konum'=>false]);DB::table('stok_parca_raf_adresleri')->updateOrInsert(['stok_parca_id'=>$v['stok_parca_id'],'depo_raf_id'=>$v['depo_raf_id']],['ana_konum'=>true,'updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Ürün raf adresine bağlandı.');}
public function parcaKaydet(Request $request){$firmaId=$this->firmaSec($request);$v=$request->validate(['oem_no'=>['required','string','max:80','regex:/^[A-Za-z0-9.\-\/ ]{5,80}$/'],'urun_kodu'=>['nullable','string','max:80'],'barkod'=>['nullable','string','max:80'],'parca_adi'=>['required','string','max:255'],'marka'=>['nullable','string','max:100'],'kategori'=>['nullable','string','max:100'],'birim'=>['nullable','string','max:20'],'kdv_orani'=>['nullable','numeric','min:0','max:100'],'alis_fiyati'=>['nullable','numeric','min:0'],'satis_fiyati'=>['nullable','numeric','min:0'],'minimum_stok'=>['nullable','numeric','min:0']]);$v['oem_no']=strtoupper(preg_replace('/\s+/','', $v['oem_no']));if(DB::table('stok_parcalar')->where('firma_id',$firmaId)->where('oem_no',$v['oem_no'])->exists())return back()->withErrors(['oem_no'=>'Bu OEM numarası bu firma için zaten kayıtlı.']);$v['barkod']=filled($v['barkod']??null)?$v['barkod']:$this->barkodOlustur($firmaId);$v['alis_fiyati']=$v['alis_fiyati']??0;$v['satis_fiyati']=filled($v['satis_fiyati']??null)?$v['satis_fiyati']:$v['alis_fiyati'];DB::table('stok_parcalar')->insert(array_merge($v,['firma_id'=>$firmaId,'stok_miktari'=>0,'oem_durum'=>'kontrol_bekliyor','aktif'=>true,'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Parça kartı oluşturuldu. Ürün barkodu: '.$v['barkod']);}
private function barkodOlustur(int $firmaId): string { do {$govde='869'.str_pad((string)$firmaId,3,'0',STR_PAD_LEFT).str_pad((string)random_int(0,999999),6,'0',STR_PAD_LEFT);$toplam=0;foreach(str_split($govde) as $i=>$rakam)$toplam+=(int)$rakam*($i%2?3:1);$kod=$govde.((10-$toplam%10)%10);} while(DB::table('stok_parcalar')->where('barkod',$kod)->exists());return $kod;}
public function hareketKaydet(Request $request){$firmaId=$this->firmaSec($request);$v=$request->validate(['stok_parca_id'=>['required','exists:stok_parcalar,id'],'depo_id'=>['required','exists:depolar,id'],'depo_raf_id'=>['required','exists:depo_raflar,id'],'cari_hesap_id'=>['nullable','exists:cari_hesaplar,id'],'yon'=>['required','in:giris,cikis'],'miktar'=>['required','numeric','gt:0'],'birim_alis_fiyati'=>['nullable','numeric','min:0'],'referans'=>['nullable','string','max:100'],'aciklama'=>['nullable','string','max:500']]);$parca=DB::table('stok_parcalar')->where('id',$v['stok_parca_id'])->where('firma_id',$firmaId)->first();abort_unless($parca&&DB::table('depo_raflar')->where('id',$v['depo_raf_id'])->where('depo_id',$v['depo_id'])->exists(),403);if(!empty($v['cari_hesap_id']))abort_unless(DB::table('cari_hesaplar')->where('id',$v['cari_hesap_id'])->where('firma_id',$firmaId)->exists(),403);if($v['yon']==='cikis'&&$parca->stok_miktari<$v['miktar'])return back()->withErrors(['miktar'=>'Yetersiz stok.']);DB::transaction(function()use($v,$parca,$firmaId){$birimAlis=(float)($v['birim_alis_fiyati']??0);$toplam=round($v['miktar']*$birimAlis*(1+((float)$parca->kdv_orani/100)),2);$hareketId=DB::table('stok_hareketleri')->insertGetId(array_merge($v,['birim_alis_fiyati'=>$birimAlis,'toplam_tutar'=>$toplam,'olusturan_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]));$guncelle=['stok_miktari'=>$parca->stok_miktari+($v['yon']==='giris'?$v['miktar']:-$v['miktar']),'updated_at'=>now()];if($v['yon']==='giris'&&$birimAlis>0){$guncelle['alis_fiyati']=$birimAlis;if((float)$parca->satis_fiyati<=0)$guncelle['satis_fiyati']=$birimAlis;}DB::table('stok_parcalar')->where('id',$parca->id)->update($guncelle);if($v['yon']==='giris'&&$toplam>0&& !empty($v['cari_hesap_id'])){$fisId=DB::table('muhasebe_fisleri')->insertGetId(['firma_id'=>$firmaId,'cari_hesap_id'=>$v['cari_hesap_id'],'fis_no'=>'STK-'.str_pad((string)$hareketId,7,'0',STR_PAD_LEFT),'tip'=>'Yedek Parça Alış Fişi','fis_tarihi'=>now()->toDateString(),'aciklama'=>$parca->parca_adi.' stok alımı','tutar'=>$toplam,'yon'=>'gider','kaynak'=>'stok_alim','kaynak_id'=>$hareketId,'durum'=>'onaylandi','olusturan_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);$net=round($v['miktar']*$birimAlis,2);DB::table('muhasebe_fis_satirlari')->insert(['muhasebe_fis_id'=>$fisId,'urun_adi'=>$parca->parca_adi,'adet'=>$v['miktar'],'birim'=>$parca->birim,'birim_fiyat'=>$birimAlis,'kdv_orani'=>$parca->kdv_orani,'kdv_haric_tutar'=>$net,'kdv_tutari'=>$toplam-$net,'kdv_dahil_tutar'=>$toplam,'created_at'=>now(),'updated_at'=>now()]);DB::table('cari_hesaplar')->where('id',$v['cari_hesap_id'])->decrement('bakiye',$toplam);}});return back()->with('success','Raf bazlı stok hareketi işlendi'.(($v['yon']==='giris'&&filled($v['birim_alis_fiyati']??null)&&filled($v['cari_hesap_id']??null))?'; gider fişi de oluşturuldu.':'.'));}}
